"""Generate the compiled catalog and source index from reviewed local assets."""

import argparse
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
ASSETS = ROOT / "assets/programs"


def generated():
    entries = json.loads((ASSETS / "catalog.json").read_text())
    lines = [
        "// Generated by assets/programs/generate.py; edit catalog.json instead.",
        "use super::{IconKind, ProgramIcon};",
        "",
        "#[rustfmt::skip]",
        "pub const PROGRAMS: &[ProgramIcon] = &[",
    ]
    docs = ["# Program icon sources", "", "Generated from `catalog.json`. Brand names identify programs, not endorsements.", "", "| Program | Artwork | License / source |", "| --- | --- | --- |"]
    kinds = {"brand": "Brand", "shell": "Shell", "generic": "Generic"}
    for entry in entries:
        if entry["kind"] not in kinds or not entry.get("source") or not entry.get("license"):
            raise ValueError(f"Incomplete icon: {entry['id']}")
        path = ASSETS / entry["asset"]
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        if digest != entry["sha256"]:
            raise ValueError(f"Unreviewed asset change: {entry['id']}")
        strings = lambda value: json.dumps(value, ensure_ascii=False)
        commands = ", ".join(map(strings, entry["commands"]))
        foreground = f"Some(0x{entry['foreground']})" if entry["foreground"] else "None"
        lines.append(
            f"    program!({strings(entry['id'])}, {strings(entry['name'])}, [{commands}], "
            f"{entry['ansi']}, 0x{entry['background']}, {foreground}, "
            f"IconKind::{kinds[entry['kind']]}, {strings(entry['asset'])}),"
        )
        source = entry.get("original_source") or entry.get("source")
        source = f"[Source]({source})" if source and source.startswith("https://") else (source or "Needs a source")
        license = entry.get("license") or "Unresolved"
        docs.append(f"| {entry['name']} | {entry['kind']} | {license} · {source} |")
    lines.extend(["];", ""])
    docs.append("")
    return {
        ROOT / "src/ui/program_icons/catalog.rs": "\n".join(lines),
        ASSETS / "SOURCES.md": "\n".join(docs),
    }


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    for path, text in generated().items():
        if args.check:
            if not path.exists() or path.read_text() != text:
                raise SystemExit(f"Regenerate {path.relative_to(ROOT)}")
        else:
            path.write_text(text)
